import hashlib
import hmac
import os
import re
import sqlite3
import unicodedata
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import json
import time
import secrets

DB_PATH = '/var/app/data/users.db'
SESSION_SECRET = os.environ.get('SESSION_SECRET', secrets.token_hex(32))

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    conn.execute('PRAGMA journal_mode=WAL')
    return conn

def init_db():
    conn = get_db()
    conn.executescript('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            email TEXT,
            is_admin INTEGER DEFAULT 0,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        );
        CREATE TABLE IF NOT EXISTS documents (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            owner_username TEXT NOT NULL,
            title TEXT NOT NULL,
            content TEXT NOT NULL,
            sensitivity TEXT DEFAULT 'normal',
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (owner_username) REFERENCES users(username)
        );
        CREATE TABLE IF NOT EXISTS audit_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            actor TEXT NOT NULL,
            action TEXT NOT NULL,
            target TEXT,
            timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        );
    ''')
    conn.commit()
    conn.close()

def normalize_username(username):
    """Normalize unicode characters in username for consistent storage and lookup.
    This prevents duplicate accounts with visually similar names."""
    normalized = unicodedata.normalize('NFKC', username)
    return normalized.lower().strip()

def hash_password(password, salt=None):
    if salt is None:
        salt = secrets.token_hex(16)
    h = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt.encode('utf-8'), 310000)
    return f"{salt}${h.hex()}"

def verify_password(password, stored_hash):
    salt, hash_val = stored_hash.split('$', 1)
    return hmac.compare_digest(
        hash_password(password, salt).split('$', 1)[1],
        hash_val
    )

def create_session_token(username):
    timestamp = str(int(time.time()))
    payload = f"{username}:{timestamp}"
    sig = hmac.new(SESSION_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}:{sig}"

def verify_session_token(token):
    try:
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None
        payload, sig = parts
        expected_sig = hmac.new(SESSION_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected_sig):
            return None
        username, timestamp = payload.rsplit(':', 1)
        if int(time.time()) - int(timestamp) > 86400:
            return None
        return username
    except (ValueError, AttributeError):
        return None

def log_audit(actor, action, target=None):
    conn = get_db()
    conn.execute(
        'INSERT INTO audit_log (actor, action, target) VALUES (?, ?, ?)',
        (actor, action, target)
    )
    conn.commit()
    conn.close()

class AppHandler(BaseHTTPRequestHandler):

    def get_current_user(self):
        auth_header = self.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return None
        token = auth_header[7:]
        return verify_session_token(token)

    def send_json(self, status, data):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode('utf-8'))

    def read_body(self):
        length = int(self.headers.get('Content-Length', 0))
        if length > 65536:
            return None
        return json.loads(self.rfile.read(length).decode('utf-8'))

    def do_POST(self):
        parsed = urlparse(self.path)

        if parsed.path == '/api/register':
            self.handle_register()
        elif parsed.path == '/api/login':
            self.handle_login()
        elif parsed.path == '/api/documents':
            self.handle_create_document()
        else:
            self.send_json(404, {'error': 'not found'})

    def do_GET(self):
        parsed = urlparse(self.path)
        params = parse_qs(parsed.query)

        if parsed.path == '/api/documents':
            self.handle_get_documents(params)
        elif parsed.path == '/api/profile':
            self.handle_get_profile(params)
        else:
            self.send_json(404, {'error': 'not found'})

    def handle_register(self):
        body = self.read_body()
        if not body:
            return self.send_json(400, {'error': 'invalid body'})

        username = body.get('username', '')
        password = body.get('password', '')
        email = body.get('email', '')

        if not username or not password:
            return self.send_json(400, {'error': 'username and password required'})

        if len(password) < 10:
            return self.send_json(400, {'error': 'password must be at least 10 characters'})

        # Normalize username for storage to prevent homoglyph attacks
        stored_username = normalize_username(username)

        if not re.match(r'^[a-z0-9_.-]{3,30}$', stored_username):
            return self.send_json(400, {'error': 'invalid username after normalization'})

        conn = get_db()
        try:
            conn.execute(
                'INSERT INTO users (username, password_hash, email) VALUES (?, ?, ?)',
                (stored_username, hash_password(password), email)
            )
            conn.commit()
            log_audit(stored_username, 'register')
            self.send_json(201, {'message': 'registered', 'username': stored_username})
        except sqlite3.IntegrityError:
            self.send_json(409, {'error': 'username already exists'})
        finally:
            conn.close()

    def handle_login(self):
        body = self.read_body()
        if not body:
            return self.send_json(400, {'error': 'invalid body'})

        username = normalize_username(body.get('username', ''))
        password = body.get('password', '')

        conn = get_db()
        user = conn.execute(
            'SELECT username, password_hash FROM users WHERE username = ?',
            (username,)
        ).fetchone()
        conn.close()

        if not user or not verify_password(password, user['password_hash']):
            # Constant-time-ish rejection
            time.sleep(0.1)
            return self.send_json(401, {'error': 'invalid credentials'})

        token = create_session_token(user['username'])
        log_audit(username, 'login')
        self.send_json(200, {'token': token, 'username': user['username']})

    def handle_get_documents(self, params):
        """Get documents for a specified user. Users can only access their own documents
        unless they are admin."""
        current_user = self.get_current_user()
        if not current_user:
            return self.send_json(401, {'error': 'authentication required'})

        # The target_user parameter specifies whose documents to retrieve
        target_user = params.get('owner', [current_user])[0]

        # Authorization check: non-admin users can only view their own documents
        # Compare the requested owner against the authenticated user's identity
        conn = get_db()
        is_admin = conn.execute(
            'SELECT is_admin FROM users WHERE username = ?',
            (current_user,)
        ).fetchone()

        if not is_admin or not is_admin['is_admin']:
            # Non-admin: verify the target is the current user
            if target_user != current_user:
                conn.close()
                log_audit(current_user, 'unauthorized_access_attempt', target_user)
                return self.send_json(403, {'error': 'access denied'})

        # Normalize the target username for database lookup
        # This ensures consistent retrieval regardless of unicode representation
        lookup_username = normalize_username(target_user)

        documents = conn.execute(
            'SELECT id, title, content, sensitivity, created_at FROM documents WHERE owner_username = ?',
            (lookup_username,)
        ).fetchall()
        conn.close()

        result = [dict(doc) for doc in documents]
        log_audit(current_user, 'view_documents', lookup_username)
        self.send_json(200, {'documents': result})

    def handle_create_document(self):
        current_user = self.get_current_user()
        if not current_user:
            return self.send_json(401, {'error': 'authentication required'})

        body = self.read_body()
        if not body:
            return self.send_json(400, {'error': 'invalid body'})

        title = body.get('title', '')[:200]
        content = body.get('content', '')[:10000]
        sensitivity = body.get('sensitivity', 'normal')

        if sensitivity not in ('normal', 'confidential', 'secret'):
            sensitivity = 'normal'

        conn = get_db()
        conn.execute(
            'INSERT INTO documents (owner_username, title, content, sensitivity) VALUES (?, ?, ?, ?)',
            (current_user, title, content, sensitivity)
        )
        conn.commit()
        conn.close()

        log_audit(current_user, 'create_document')
        self.send_json(201, {'message': 'document created'})

    def handle_get_profile(self, params):
        current_user = self.get_current_user()
        if not current_user:
            return self.send_json(401, {'error': 'authentication required'})

        conn = get_db()
        user = conn.execute(
            'SELECT username, email, created_at FROM users WHERE username = ?',
            (current_user,)
        ).fetchone()
        conn.close()

        if not user:
            return self.send_json(404, {'error': 'user not found'})

        self.send_json(200, dict(user))


if __name__ == '__main__':
    init_db()
    server = HTTPServer(('127.0.0.1', 8080), AppHandler)
    server.serve_forever()
